// ─────────────────────────────────────────────
// Merge & Structure GitHub Data for Claude
// ─────────────────────────────────────────────

// Pull data from all three parallel fetch nodes
const commitsRaw = $node["Fetch Commits"].json.body || $node["Fetch Commits"].json;
const issuesRaw = $node["Fetch Closed Issues"].json.body || $node["Fetch Closed Issues"].json;
const prsRaw = $node["Fetch Merged PRs"].json.body || $node["Fetch Merged PRs"].json;

// Ensure arrays
const commits = Array.isArray(commitsRaw) ? commitsRaw : [];
const issues = Array.isArray(issuesRaw) ? issuesRaw : [];
const prs = Array.isArray(prsRaw) ? prsRaw : [];

// Filter: only truly merged PRs (not just closed)
const mergedPRs = prs.filter(pr => pr.merged_at != null);

// Filter: exclude PRs from issues endpoint (GitHub returns PRs as issues)
const pureIssues = issues.filter(issue => !issue.pull_request);

// Config passthrough
const config = $node["Set Config Variables"].json;

// Compute stats
const allAuthors = [
  ...commits.map(c => c.author?.login || c.commit?.author?.name).filter(Boolean),
  ...pureIssues.map(i => i.user?.login).filter(Boolean),
  ...mergedPRs.map(p => p.user?.login).filter(Boolean),
];
const uniqueAuthors = [...new Set(allAuthors)];

// Build structured payload
const summaryData = {
  repo: config.GITHUB_REPO || 'unknown/repo',
  weekStart: config.weekStart,
  weekEnd: config.weekEnd,
  language: config.LANGUAGE || 'en',
  stats: {
    totalCommits: commits.length,
    totalClosedIssues: pureIssues.length,
    totalMergedPRs: mergedPRs.length,
    uniqueAuthors: uniqueAuthors.length,
    topContributors: uniqueAuthors.slice(0, 5),
  },
  commits: commits.slice(0, 50).map(c => ({
    sha: (c.sha || '').slice(0, 7),
    message: (c.commit?.message || '').split('\n')[0],
    author: c.author?.login || c.commit?.author?.name || 'unknown',
    date: c.commit?.author?.date,
  })),
  closedIssues: pureIssues.slice(0, 30).map(i => ({
    number: i.number,
    title: i.title,
    author: i.user?.login || 'unknown',
    closedAt: i.closed_at,
    labels: (i.labels || []).map(l => (typeof l === 'string' ? l : l.name)).filter(Boolean),
  })),
  mergedPRs: mergedPRs.slice(0, 30).map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'unknown',
    mergedAt: p.merged_at,
    additions: p.additions || 0,
    deletions: p.deletions || 0,
    changedFiles: p.changed_files || 0,
  })),
};

return [{ json: { summaryData, config } }];

// Extract the text summary from Claude's API response
const response = $input.first().json;

// Claude response shape: { content: [{ type: 'text', text: '...' }], ... }
const summary = response.content?.[0]?.text 
  || '⚠️ No summary was generated by Claude.';

const repo = $node["Set Config Variables"].json.GITHUB_REPO || 'unknown/repo';
const weekEnd = $node["Set Config Variables"].json.weekEnd || 'this week';

return [{ json: { summary, repo, weekEnd } }];
